-- PHASE B, WORKING DRAFT 04: monitoring intent, Wanted, request intent and notifications.
-- Based on Features/Monitoring/CODEMAP.md, Acquisition/Wanted/CODEMAP.md,
-- docs/mockups/admin-notifications/SPEC.md and open notification PR #842.
-- No live-DB change; remaining non-notification seed contracts are tracked in B01.
-- Run after parts 01..03 ONLY against an isolated disposable PostgreSQL database.
BEGIN;

-- A missing monitoring row means inherit. No duplicate effective-monitored state.
CREATE TABLE "WorkMonitoringDecisions" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "WorkId" bigint NOT NULL,
    "WorkSeasonId" bigint,
    "WorkEpisodeId" bigint,
    "WorkVolumeId" bigint,
    "WorkChapterId" bigint,
    "WorkTrackId" bigint,
    "WorkEditionId" bigint,
    "IsMonitored" boolean NOT NULL,
    CONSTRAINT "PK_WorkMonitoringDecisions" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WorkMonitoringDecisions_Works" FOREIGN KEY ("WorkId") REFERENCES "Works" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkSeasons" FOREIGN KEY ("WorkSeasonId","WorkId") REFERENCES "WorkSeasons" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkEpisodes" FOREIGN KEY ("WorkEpisodeId","WorkId") REFERENCES "WorkEpisodes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkVolumes" FOREIGN KEY ("WorkVolumeId","WorkId") REFERENCES "WorkVolumes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkChapters" FOREIGN KEY ("WorkChapterId","WorkId") REFERENCES "WorkChapters" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkTracks" FOREIGN KEY ("WorkTrackId","WorkId") REFERENCES "WorkTracks" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringDecisions_WorkEditions" FOREIGN KEY ("WorkEditionId","WorkId") REFERENCES "WorkEditions" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "CK_WorkMonitoringDecisions_OneTarget" CHECK (
        num_nonnulls("WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") <= 1)
);
CREATE UNIQUE INDEX "UX_WorkMonitoringDecisions_Target" ON "WorkMonitoringDecisions"
    ("WorkId","WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") NULLS NOT DISTINCT;
-- No IsEffective, no modes (Future/All): those are derived decisions/workflows.

CREATE TABLE "MonitoringRelationTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_MonitoringRelationTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_MonitoringRelationTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_MonitoringRelationTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_MonitoringRelationTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "MonitoringRelationTypes" ("Id", "Key")
VALUES
    (1, 'person'),
    (2, 'studio'),
    (3, 'collection'),
    (4, 'artist');

CREATE FUNCTION "IsMonitoringRoleFilterValid"(roles text[]) RETURNS boolean
LANGUAGE sql IMMUTABLE STRICT AS $role_filter$
    SELECT
        cardinality(roles) BETWEEN 1 AND 20
        AND array_ndims(roles) = 1
        AND NOT EXISTS (
            SELECT
                1
            FROM
                unnest(roles) AS role(name)
            WHERE
                role.name IS NULL
                OR length(role.name) NOT BETWEEN 1 AND 100
                OR role.name <> lower(btrim(role.name))
        )
        AND (SELECT count(DISTINCT role.name) FROM unnest(roles) AS role(name)) = cardinality(roles)
$role_filter$;

CREATE TABLE "WorkMonitoringSources" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MonitoringRelationTypeId" smallint NOT NULL,
    "PersonId" bigint,
    "StudioName" varchar(200),
    "CollectionId" bigint,
    "MusicArtistId" bigint,
    "RoleNames" text[],
    "AddedByProfileId" bigint NOT NULL,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_WorkMonitoringSources" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WorkMonitoringSources_Types" FOREIGN KEY ("MonitoringRelationTypeId") REFERENCES "MonitoringRelationTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringSources_People" FOREIGN KEY ("PersonId") REFERENCES "People" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringSources_Artists" FOREIGN KEY ("MusicArtistId") REFERENCES "MusicArtists" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringSources_Collections" FOREIGN KEY ("CollectionId", "AddedByProfileId") REFERENCES "Collections" ("Id", "ProfileId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMonitoringSources_Profiles" FOREIGN KEY ("AddedByProfileId") REFERENCES "Profiles" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_WorkMonitoringSources_Target" UNIQUE NULLS NOT DISTINCT ("MonitoringRelationTypeId", "PersonId", "StudioName", "CollectionId", "MusicArtistId"),
    CONSTRAINT "CK_WorkMonitoringSources_Target" CHECK (
        num_nonnulls("PersonId", "StudioName", "CollectionId", "MusicArtistId") = 1
        AND CASE "MonitoringRelationTypeId"
            WHEN 1 THEN "PersonId" IS NOT NULL
            WHEN 2 THEN "StudioName" IS NOT NULL AND length("StudioName") > 0 AND "StudioName" = lower(btrim("StudioName"))
            WHEN 3 THEN "CollectionId" IS NOT NULL
            WHEN 4 THEN "MusicArtistId" IS NOT NULL
            ELSE FALSE
        END),
    CONSTRAINT "CK_WorkMonitoringSources_Roles" CHECK (
        "RoleNames" IS NULL OR ("MonitoringRelationTypeId" = 1 AND "IsMonitoringRoleFilterValid"("RoleNames")))
);
CREATE INDEX "IX_WorkMonitoringSources_Person" ON "WorkMonitoringSources" ("PersonId") WHERE "PersonId" IS NOT NULL;
CREATE INDEX "IX_WorkMonitoringSources_Artist" ON "WorkMonitoringSources" ("MusicArtistId") WHERE "MusicArtistId" IS NOT NULL;
CREATE INDEX "IX_WorkMonitoringSources_Collection" ON "WorkMonitoringSources" ("CollectionId") WHERE "CollectionId" IS NOT NULL;
CREATE INDEX "IX_WorkMonitoringSources_Studio" ON "WorkMonitoringSources" ("StudioName") WHERE "StudioName" IS NOT NULL;
CREATE INDEX "IX_WorkMonitoringSources_Profile" ON "WorkMonitoringSources" ("AddedByProfileId");

-- Concrete request intent persists only for the approved, open request; not inferred later.
ALTER TABLE "AcquisitionRequests" ADD CONSTRAINT "UX_AcquisitionRequests_Id_WorkId" UNIQUE ("Id","WorkId");
CREATE TABLE "AcquisitionRequestTargets" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "AcquisitionRequestId" bigint NOT NULL,
    "WorkId" bigint NOT NULL,
    "WorkSeasonId" bigint,
    "WorkEpisodeId" bigint,
    "WorkVolumeId" bigint,
    "WorkChapterId" bigint,
    "WorkTrackId" bigint,
    "WorkEditionId" bigint,
    CONSTRAINT "PK_AcquisitionRequestTargets" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AcquisitionRequestTargets_AcquisitionRequests" FOREIGN KEY ("AcquisitionRequestId","WorkId") REFERENCES "AcquisitionRequests" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkSeasons" FOREIGN KEY ("WorkSeasonId","WorkId") REFERENCES "WorkSeasons" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkEpisodes" FOREIGN KEY ("WorkEpisodeId","WorkId") REFERENCES "WorkEpisodes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkVolumes" FOREIGN KEY ("WorkVolumeId","WorkId") REFERENCES "WorkVolumes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkChapters" FOREIGN KEY ("WorkChapterId","WorkId") REFERENCES "WorkChapters" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkTracks" FOREIGN KEY ("WorkTrackId","WorkId") REFERENCES "WorkTracks" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_AcquisitionRequestTargets_WorkEditions" FOREIGN KEY ("WorkEditionId","WorkId") REFERENCES "WorkEditions" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "CK_AcquisitionRequestTargets_OneTarget" CHECK (
        num_nonnulls("WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") <= 1)
);
CREATE UNIQUE INDEX "UX_AcquisitionRequestTargets_ExactTarget" ON "AcquisitionRequestTargets"
    ("AcquisitionRequestId","WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") NULLS NOT DISTINCT;

-- Exactly one canonical wanted row for each missing/upgrade target.
-- "missing" vs "upgrade" is resolved from held coverage, never duplicated in this table.
CREATE TABLE "WantedItems" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "WorkId" bigint NOT NULL,
    "WorkSeasonId" bigint,
    "WorkEpisodeId" bigint,
    "WorkVolumeId" bigint,
    "WorkChapterId" bigint,
    "WorkTrackId" bigint,
    "WorkEditionId" bigint,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_WantedItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_WantedItems_Works" FOREIGN KEY ("WorkId") REFERENCES "Works" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkSeasons" FOREIGN KEY ("WorkSeasonId","WorkId") REFERENCES "WorkSeasons" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkEpisodes" FOREIGN KEY ("WorkEpisodeId","WorkId") REFERENCES "WorkEpisodes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkVolumes" FOREIGN KEY ("WorkVolumeId","WorkId") REFERENCES "WorkVolumes" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkChapters" FOREIGN KEY ("WorkChapterId","WorkId") REFERENCES "WorkChapters" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkTracks" FOREIGN KEY ("WorkTrackId","WorkId") REFERENCES "WorkTracks" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WantedItems_WorkEditions" FOREIGN KEY ("WorkEditionId","WorkId") REFERENCES "WorkEditions" ("Id","WorkId") ON DELETE RESTRICT,
    CONSTRAINT "CK_WantedItems_OneTarget" CHECK (
        num_nonnulls("WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") <= 1)
);
CREATE UNIQUE INDEX "UX_WantedItems_ExactTarget" ON "WantedItems"
    ("WorkId","WorkSeasonId","WorkEpisodeId","WorkVolumeId","WorkChapterId","WorkTrackId","WorkEditionId") NULLS NOT DISTINCT;
CREATE INDEX "IX_WantedItems_CreatedAt" ON "WantedItems" ("CreatedAt","Id");
-- WantedReconciler is the ONLY writer. Operations is the shared execution queue.

-- Current event catalog is defined by code and translated by UiTranslationMessages.
-- No second user notification preference model and no automatic push/email delivery claims.
CREATE TABLE "NotificationEventCategoryTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    "EventAudienceTypeId" smallint NOT NULL,
    "EventSeverityTypeId" smallint NOT NULL,
    CONSTRAINT "PK_NotificationEventCategoryTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_NotificationEventCategoryTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "UX_NotificationEventCategoryTypes_Policy" UNIQUE ("Id", "EventAudienceTypeId", "EventSeverityTypeId"),
    CONSTRAINT "CK_NotificationEventCategoryTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_NotificationEventCategoryTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "NotificationEventCategoryTypes" ("Id", "Key", "EventAudienceTypeId", "EventSeverityTypeId")
VALUES
    (1, 'download_grabbed', 1, 1),
    (2, 'download_failed', 1, 2),
    (3, 'import_completed', 1, 1),
    (4, 'import_failed', 1, 2),
    (5, 'release_available', 1, 1),
    (6, 'request_approved', 1, 1),
    (7, 'request_denied', 1, 1),
    (8, 'storage_problem', 2, 3);
