CREATE TABLE "NotificationSubscriptions" (
    "ProfileId" bigint NOT NULL,
    "NotificationEventCategoryTypeId" smallint NOT NULL,
    "IsEnabled" boolean NOT NULL,
    "NotificationTimingTypeId" smallint NOT NULL,
    "UpdatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_NotificationSubscriptions" PRIMARY KEY ("ProfileId","NotificationEventCategoryTypeId"),
    CONSTRAINT "FK_NotificationSubscriptions_Profiles" FOREIGN KEY ("ProfileId") REFERENCES "Profiles" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_NotificationSubscriptions_NotificationEventCategoryTypes" FOREIGN KEY ("NotificationEventCategoryTypeId") REFERENCES "NotificationEventCategoryTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_NotificationSubscriptions_NotificationTimingTypes" FOREIGN KEY ("NotificationTimingTypeId") REFERENCES "NotificationTimingTypes" ("Id") ON DELETE RESTRICT
